const app=document.querySelector('#app');
const state={data:null,selected:new Set(),search:'',department:'',detail:null,detailDirty:false,detailSaveError:'',detailKey:'',detailIdentity:'',detailBackupAvailable:false,detailBackupError:'',review:null,localBackupNotice:'',diagnostic:false};
const icon=(name)=>({upload:'↑',file:'▱',search:'⌕',close:'×',eye:'○',download:'↓'}[name]||'');
const timeLabels={shift1_start:'Tempo 1, entrada',shift1_end:'Tempo 1, saída',shift2_start:'Tempo 2, entrada',shift2_end:'Tempo 2, saída',overtime_start:'Hora extra, entrada',overtime_end:'Hora extra, saída'};
const fmt=value=>value?value.split('-').reverse().join('/'):'Não identificado';
const formatDuration=minutes=>`${Math.floor(minutes/60)}h ${String(minutes%60).padStart(2,'0')}min`;
const formatBalance=minutes=>minutes==null?'—':`${minutes<0?'-':minutes>0?'+':''}${formatDuration(Math.abs(minutes))}`;
const lunchBreakMinutes=90;
const timePairs=[['shift1_start','shift1_end'],['shift2_start','shift2_end'],['overtime_start','overtime_end']];
const coreFields=timePairs.slice(0,2).flat();
const draftFields=timePairs.flat();
const draftPrefix='ponto-local-draft-v1:';
function draftIdentity(employee){return JSON.stringify([state.data?.filename,employee.employee_number,employee.name,employee.period_start,employee.period_end,employee.records.map(record=>[record.date,...draftFields.map(field=>record[field]||'')])])}
function draftKey(identity){let hash=2166136261;for(let i=0;i<identity.length;i++)hash=Math.imul(hash^identity.charCodeAt(i),16777619);return draftPrefix+(hash>>>0).toString(16)}
function validDraftTime(value){if(value==null||value==='')return true;if(!/^\d{2}:\d{2}$/.test(value))return false;const [hour,minute]=value.split(':').map(Number);return hour<24&&minute<60}
function restoreDraft(employee,key,identity){try{const raw=localStorage.getItem(key);if(!raw)return null;const draft=JSON.parse(raw);if(draft.identity!==identity||!Array.isArray(draft.records)||draft.records.length!==employee.records.length)return null;for(let index=0;index<employee.records.length;index++){const source=employee.records[index],saved=draft.records[index];if(saved.date!==source.date||!draftFields.every(field=>validDraftTime(saved[field])))return null}let changed=false;employee.records.forEach((record,index)=>draftFields.forEach(field=>{const value=draft.records[index][field]||null;if(record[field]!==value)changed=true;record[field]=value}));return{changed}}catch{return null}}
function saveDraft(){if(!state.detailKey||!state.detail)return false;try{localStorage.setItem(state.detailKey,JSON.stringify({identity:state.detailIdentity,records:state.detail.records.map(record=>({date:record.date,...Object.fromEntries(draftFields.map(field=>[field,record[field]||null]))})),saved_at:new Date().toISOString()}));state.detailBackupAvailable=true;state.detailBackupError='';state.localBackupNotice='';return true}catch(error){state.detailBackupError=error.name==='QuotaExceededError'?'Armazenamento local cheio; salve as alterações antes de sair.':'Não foi possível criar cópia local; salve as alterações antes de sair.';return false}}
function pairMinutes(start,end){if(!start||!end)return 0;const minutes=value=>{const [hour,minute]=value.split(':').map(Number);return hour*60+minute};let span=minutes(end)-minutes(start);if(span<0)span+=24*60;return span}
function lunchMinutes(record){if(!coreFields.every(field=>record[field]))return null;return pairMinutes(record.shift1_end,record.shift2_start)}
function lunchLabel(record){const minutes=record.lunch_minutes;if(minutes==null)return'—';const duration=formatDuration(minutes);if(minutes>lunchBreakMinutes){const excess=minutes-lunchBreakMinutes;return`${duration} · +${excess<60?`${excess}min`:formatDuration(excess)}`}if(minutes<lunchBreakMinutes)return`${duration} · ajustado a 1h30`;return duration}
function recordMinutes(record){if(!coreFields.every(field=>record[field]))return null;let total=timePairs.reduce((sum,[startField,endField])=>sum+pairMinutes(record[startField],record[endField]),0);const lunch=lunchMinutes(record);if(lunch!=null&&lunch<lunchBreakMinutes)total-=lunchBreakMinutes-lunch;return total}
function incompletePairs(records){return records.reduce((total,record)=>total+timePairs.filter(([start,end])=>Boolean(record[start])!==Boolean(record[end])).length,0)}
function expectedMinutes(isoDate){const [year,month,day]=isoDate.split('-').map(Number);const weekday=new Date(year,month-1,day,12).getDay();return weekday>=1&&weekday<=4?540:weekday===5?480:0}
function dateKey(value){return `${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}-${String(value.getDate()).padStart(2,'0')}`}
function calculateWorkload(employee){
  const fields=timePairs.flat();let total=0,count=0,days=0;const weeks=new Map();
  for(const record of employee.records){
    const dayCount=fields.filter(field=>record[field]).length;count+=dayCount;if(dayCount)days++;
    record.lunch_minutes=lunchMinutes(record);record.lunch_excess_minutes=record.lunch_minutes==null?null:Math.max(0,record.lunch_minutes-lunchBreakMinutes);record.lunch_time=lunchLabel(record);record.worked_minutes=recordMinutes(record);record.required_minutes=expectedMinutes(record.date);
    record.worked_time=record.worked_minutes!=null?formatDuration(record.worked_minutes):!dayCount&&!record.required_minutes?'Sem expediente':'Sem registro de ponto';
    record.required_time=record.required_minutes?formatDuration(record.required_minutes):dayCount?'Hora extra':'—';
    record.balance_minutes=record.worked_minutes==null||!record.required_minutes?null:record.worked_minutes-record.required_minutes;
    record.balance_time=formatBalance(record.balance_minutes);record.has_incomplete_day=dayCount>0&&record.worked_minutes==null;
    if(record.worked_minutes!=null)total+=record.worked_minutes;
    const [year,month,day]=record.date.split('-').map(Number);const weekDate=new Date(year,month-1,day,12);
    weekDate.setDate(weekDate.getDate()-((weekDate.getDay()+6)%7));const weekStart=dateKey(weekDate);
    weeks.set(weekStart,(weeks.get(weekStart)||0)+(record.worked_minutes||0));
  }
  employee.worked_minutes=total;employee.worked_time=formatDuration(total);employee.expected_minutes=220*60;
  employee.expected_time=formatDuration(employee.expected_minutes);employee.balance_minutes=total-employee.expected_minutes;
  employee.balance_time=formatBalance(employee.balance_minutes);employee.incomplete_pair_count=incompletePairs(employee.records);
  employee.incomplete_day_count=employee.records.filter(record=>record.has_incomplete_day).length;
  employee.lunch_excess_day_count=employee.records.filter(record=>record.lunch_excess_minutes>0).length;
  employee.time_count=count;employee.days_with_records=days;
  employee.weekly_summaries=[...weeks].sort(([a],[b])=>a.localeCompare(b)).map(([week_start,worked_minutes])=>{
    const end=new Date(`${week_start}T12:00:00`);end.setDate(end.getDate()+6);
    return{week_start,week_end:dateKey(end),worked_minutes,worked_time:formatDuration(worked_minutes),expected_minutes:44*60,
      expected_time:formatDuration(44*60),balance_minutes:worked_minutes-44*60,balance_time:formatBalance(worked_minutes-44*60)};
  });
  return employee;
}
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const url=path=>`/api/session/${state.data.session_id}${path}`;
const download=path=>location.href=url(path);

function render(){
  const employees=filtered();
  app.innerHTML=`<header><div class="brand"><span class="brand-mark">CP</span><div><h1>Controle de Ponto</h1><span><i></i>Processamento local · seus dados não saem deste computador</span></div></div>${state.data?'<button class="text-button" data-action="reset">Importar outro arquivo</button>':''}</header>
  <main><div class="dropzone" id="dropzone" role="button" tabindex="0"><input id="file" type="file" accept=".xls,.xlsx" hidden><div class="drop-icon">${icon('upload')}</div><strong>Arraste e solte o arquivo XLS ou XLSX</strong><span>ou clique para selecionar</span><small>Formatos aceitos: .xls e .xlsx</small></div><div id="message"></div>
  ${state.data?summary()+backupNotice()+`<div class="section-title"><div><h2>Funcionários com ponto</h2><p>Somente pessoas com pelo menos uma marcação real aparecem nesta lista.</p></div><button class="text-button" data-action="diagnostic">${state.diagnostic?'Ocultar diagnóstico':`Ver ${state.data.excluded_count} ignorados`}</button></div>${diagnostic()}${toolbar(employees)}${table(employees)}`:''}</main>
  ${state.data?actionBar():''}${state.detail?drawer():''}${state.review?reviewDialog():''}`;
  bind();
}
function localDraftCount(){try{return Object.keys(localStorage).filter(key=>key.startsWith(draftPrefix)).length}catch{return 0}}
function backupNotice(){const draftCount=localDraftCount();const explanation=state.localBackupNotice?`<span role="status">${esc(state.localBackupNotice)}</span>`:'<span><strong>Rascunhos automáticos locais</strong> · ficam neste navegador e computador. Para recuperar após reiniciar, reimporte a mesma planilha e abra a ficha.</span>';return `<aside class="backup-notice">${explanation}<button class="text-button" data-action="clear-backups" data-backup-count ${draftCount?'':'disabled'}>Apagar cópias locais (${draftCount})</button></aside>`}
function summary(){const d=state.data;return `<section class="summary"><div class="file-summary"><span class="drop-icon">${icon('file')}</span><div><strong>${esc(d.filename)}</strong><span>Arquivo processado com sucesso</span></div></div><div class="metric"><span>Período</span><strong class="period">${fmt(d.period_start)} a ${fmt(d.period_end)}</strong></div><div class="metric"><span>Identificados</span><strong>${d.identified_count}</strong></div><div class="metric good"><span>Com horários</span><strong>${d.included_count}</strong></div><div class="metric muted"><span>Ignorados</span><strong>${d.excluded_count}</strong></div></section>`}
function diagnostic(){if(!state.diagnostic)return'';return `<div class="diagnostic"><strong>Ignorados sem horário</strong>${state.data.excluded.map(item=>`<span>${esc(item.name||'Sem nome')} · ${esc(item.department||'Sem departamento')} · nenhum horário encontrado</span>`).join('')}</div>`}
function filtered(){if(!state.data)return[];return state.data.employees.filter(item=>item.name.toLocaleLowerCase('pt-BR').includes(state.search.toLocaleLowerCase('pt-BR'))&&(!state.department||item.department===state.department)).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'))}
function toolbar(employees){const departments=[...new Set(state.data.employees.map(item=>item.department).filter(Boolean))].sort();return `<div class="toolbar"><label class="search"><span>${icon('search')}</span><input id="search" value="${esc(state.search)}" placeholder="Buscar funcionário por nome"></label><label class="select-label">Departamento<select id="department"><option value="">Todos os departamentos</option>${departments.map(item=>`<option ${item===state.department?'selected':''}>${esc(item)}</option>`).join('')}</select></label><span class="count">${employees.length} funcionários</span></div>`}
function table(employees){const all=employees.length&&employees.every(item=>state.selected.has(item.id));return `<div class="table-frame"><table class="employee-table"><thead><tr><th class="check"><input id="all" type="checkbox" ${all?'checked':''}></th><th>Funcionário</th><th>Departamento</th><th>Dias com registros</th><th>Total de marcações</th><th>Jornada realizada</th><th>Saldo do período</th><th>Ações</th></tr></thead><tbody>${employees.map(item=>`<tr class="${state.selected.has(item.id)?'selected':''}" data-employee-row="${item.id}"><td class="check"><input class="employee-check" data-id="${item.id}" type="checkbox" ${state.selected.has(item.id)?'checked':''}></td><td><strong>${esc(item.name)}</strong><small>Tra. No. ${esc(item.employee_number)}</small></td><td>${esc(item.department||'Não informado')}</td><td>${item.days_with_records}</td><td>${item.time_count}</td><td><strong data-worked-value>${esc(item.worked_time??'Cálculo indisponível')}</strong><small>meta ${esc(item.expected_time??formatDuration(220*60))}</small>${item.incomplete_day_count?`<small class="incomplete-warning">${item.incomplete_day_count} dia(s) sem quatro horários</small>`:''}${item.incomplete_pair_count?`<small class="incomplete-warning">${item.incomplete_pair_count} marcação(ões) sem par</small>`:''}${item.lunch_excess_day_count?`<small class="incomplete-warning">${item.lunch_excess_day_count} almoço(s) acima de 1h30</small>`:''}</td><td><strong data-balance-value>${esc(item.balance_time??formatBalance((item.worked_minutes??0)-220*60))}</strong></td><td><div class="row-actions"><button class="button primary small" data-view="${item.id}">Visualizar</button><button class="button secondary small" data-pdf="${item.id}">PDF</button></div></td></tr>`).join('')}</tbody></table>${employees.length?'':'<div class="empty">Nenhum funcionário corresponde aos filtros.</div>'}</div>`}
function actionBar(){return `<footer class="action-bar"><span><strong>${state.selected.size}</strong> funcionário${state.selected.size===1?'':'s'} selecionado${state.selected.size===1?'':'s'}</span><div><button class="button primary" data-action="selected" ${state.selected.size?'':'disabled'}>Gerar PDFs selecionados</button><button class="button secondary" data-action="allzip">Gerar todos em ZIP</button><button class="button secondary" data-action="combined" ${state.selected.size?'':'disabled'}>Gerar PDF único</button></div></footer>`}
function timeInput(value,index,field){return `<input class="time-edit" type="time" aria-label="${timeLabels[field]}" title="${timeLabels[field]}" data-record="${index}" data-field="${field}" value="${esc(value||'')}">`}
function weeklySummary(employee){return `<section class="weekly-summary"><h4>Resumo semanal · meta de 44h por semana</h4><div>${employee.weekly_summaries.map((week,index)=>`<article><strong>Semana ${index+1}</strong><small>${fmt(week.week_start)} a ${fmt(week.week_end)}</small><span>Realizada: ${esc(week.worked_time)}</span><span>Saldo: ${esc(week.balance_time)}</span></article>`).join('')}</div></section>`}
function recordTotals(employee){return employee.records.reduce((total,record)=>{total.required+=(record.required_minutes||0);if(record.worked_minutes!=null)total.worked+=record.worked_minutes;return total},{required:0,worked:0,balance:0})}
function finalizeRecordTotals(totals){totals.balance=totals.worked-totals.required;return totals}
function showLunch(cell,record){cell.textContent=record.lunch_time??'—';cell.className=`lunch-time${record.lunch_excess_minutes>0?' lunch-exceeded':record.lunch_minutes!=null&&record.lunch_minutes<lunchBreakMinutes?' lunch-adjusted':''}`}
function addLunchColumn(){
  const table=document.querySelector('.record-table');if(!table||!state.detail)return;
  const heading=document.createElement('th');heading.rowSpan=2;heading.textContent='Almoço';heading.title='Intervalo com desconto fixo mínimo de 1h30. Se passar, o excedente aparece aqui.';table.tHead.rows[0].cells[2].after(heading);
  [...table.tBodies[0].rows].forEach((row,index)=>{const cell=document.createElement('td');cell.dataset.lunch=String(index);showLunch(cell,state.detail.records[index]);row.cells[3].after(cell)});
  table.tFoot.rows[0].cells[0].colSpan=9;
}
function drawer(){const e=state.detail,totals=finalizeRecordTotals(recordTotals(e));return `<div class="drawer-backdrop"><aside class="drawer"><div class="drawer-head"><div><h2>Ficha do funcionário</h2><h3>${esc(e.name)}</h3><p>${esc(e.department||'Departamento não informado')} · Tra. No. ${esc(e.employee_number)}</p><p>${fmt(e.period_start)} a ${fmt(e.period_end)}</p></div><button class="icon-button" data-action="close">${icon('close')}</button></div><div class="drawer-stats"><span><strong id="detail-days">${e.days_with_records}</strong> dias com registro</span><span><strong id="detail-count">${e.time_count}</strong> marcações</span><span>Realizada: <strong id="detail-worked">${esc(e.worked_time)}</strong></span><span>Meta: <strong id="detail-expected">${esc(e.expected_time)}</strong></span><span>Saldo: <strong id="detail-balance">${esc(e.balance_time)}</strong></span>${e.incomplete_day_count?`<span id="incomplete-warning" class="incomplete-warning">${e.incomplete_day_count} dia(s) sem os quatro horários principais. Não contabilizado(s), conforme a calculadora.</span>`:''}${e.lunch_excess_day_count?`<span id="lunch-warning" class="incomplete-warning">${e.lunch_excess_day_count} intervalo(s) de almoço acima de 1h30; o excedente está destacado na tabela.</span>`:''}</div>${weeklySummary(e)}<div class="record-scroll"><table class="record-table"><thead><tr><th>Data</th><th>Semana</th><th colspan="2">Tem. 1</th><th colspan="2">Tem. 2</th><th colspan="2">Hora extra</th><th>Obrigatórias</th><th>Trabalhadas</th><th>Saldo do dia</th></tr><tr><th></th><th></th><th>Entrada</th><th>Saída</th><th>Entrada</th><th>Saída</th><th>Entrada</th><th>Saída</th><th></th><th></th><th></th></tr></thead><tbody>${e.records.map((r,index)=>`<tr><td>${esc(r.date_label)}</td><td>${esc(r.weekday)}</td><td>${timeInput(r.shift1_start,index,'shift1_start')}</td><td>${timeInput(r.shift1_end,index,'shift1_end')}</td><td>${timeInput(r.shift2_start,index,'shift2_start')}</td><td>${timeInput(r.shift2_end,index,'shift2_end')}</td><td>${timeInput(r.overtime_start,index,'overtime_start')}</td><td>${timeInput(r.overtime_end,index,'overtime_end')}</td><td class="daily-required" data-daily-required="${index}">${esc(r.required_time)}</td><td class="daily-total" data-daily-total="${index}">${esc(r.worked_time)}</td><td class="daily-balance" data-daily-balance="${index}">${esc(r.balance_time)}</td></tr>`).join('')}</tbody><tfoot><tr><th colspan="8">TOTAL DO PERÍODO</th><th id="detail-required-total">${formatDuration(totals.required)}</th><th id="detail-worked-total">${formatDuration(totals.worked)}</th><th id="detail-balance-total">${formatBalance(totals.balance)}</th></tr></tfoot></table></div><div class="signature">Assinatura do funcionário</div><div class="edit-footer"><span id="edit-status" class="${state.detailSaveError||state.detailBackupError?'save-error':''}" role="status">${state.detailSaveError?esc(state.detailSaveError):state.detailBackupError?esc(state.detailBackupError):state.detailDirty?(state.detailBackupAvailable?'Rascunho salvo neste navegador; salve para aplicar nesta sessão.':'Alterações não salvas.'):state.detailBackupAvailable?'Salvo nesta sessão; há uma cópia local para recuperação.':'Edite os horários e salve antes de gerar o PDF.'}</span><div class="drawer-actions"><button class="button secondary" data-action="save-detail" ${state.detailDirty?'':'disabled'}>Salvar alterações</button><button class="button primary" data-action="detail-pdf">Gerar PDF</button><button class="button secondary" data-action="print">Imprimir visualização</button></div></div></aside></div>`}

function reviewDialog(){const review=state.review;const employees=review.ids==null?state.data.employees:state.data.employees.filter(item=>review.ids.includes(item.id));const incomplete=employees.reduce((total,item)=>total+(item.incomplete_day_count||0),0);const incompletePairsTotal=employees.reduce((total,item)=>total+(item.incomplete_pair_count||0),0);const overLunchtime=employees.reduce((total,item)=>total+(item.lunch_excess_day_count||0),0);const needsReview=employees.filter(item=>item.incomplete_day_count||item.incomplete_pair_count||item.lunch_excess_day_count);const label=review.kind==='combined'?'PDF único':review.kind==='allzip'?'ZIP de todos os funcionários':review.kind==='selected'?'ZIP dos funcionários selecionados':'PDF individual';return `<div class="review-backdrop"><section class="review-dialog" role="dialog" aria-modal="true" aria-labelledby="review-title"><h2 id="review-title">Conferir antes de gerar</h2><p>Você vai gerar: <strong>${label}</strong></p><div class="review-metrics"><span><strong>${employees.length}</strong> funcionário(s)</span><span><strong>${incomplete}</strong> dia(s) sem os quatro horários principais</span><span><strong>${incompletePairsTotal}</strong> marcação(ões) sem par</span><span><strong>${overLunchtime}</strong> almoço(s) acima de 1h30</span></div>${needsReview.length?`<div class="review-issues"><strong>Verifique estes registros:</strong><ul>${needsReview.map(item=>`<li><strong>${esc(item.name)}</strong>${item.incomplete_day_count?` · ${item.incomplete_day_count} dia(s) sem horários principais`:''}${item.incomplete_pair_count?` · ${item.incomplete_pair_count} marcação(ões) sem par`:''}${item.lunch_excess_day_count?` · ${item.lunch_excess_day_count} intervalo(s) acima de 1h30`:''}</li>`).join('')}</ul></div>`:'<p class="review-clear">Nenhuma pendência de horário incompleto ou almoço excedente foi identificada.</p>'}${state.detailDirty&&review.kind==='detail'?'<p class="review-note">As alterações abertas serão salvas antes da geração.</p>':''}<div class="review-actions"><button class="button secondary" data-action="cancel-export">Voltar</button><button class="button primary" data-action="confirm-export">Gerar agora</button></div></section></div>`}

function bindRecordResize(){
  const panel=document.querySelector('.record-scroll');if(!panel)return;
  const handle=document.createElement('button');handle.type='button';handle.className='record-resize-handle';
  handle.setAttribute('aria-label','Arraste ou use as setas para ajustar a altura da tabela');
  handle.textContent='↕ Arraste para aumentar ou diminuir a tabela';panel.after(handle);
  const savedHeight=Number(localStorage.getItem('ponto-record-scroll-height'));
  if(savedHeight>=160)panel.style.height=`${savedHeight}px`;
  const saveHeight=height=>{const value=Math.max(160,Math.round(height));panel.style.height=`${value}px`;localStorage.setItem('ponto-record-scroll-height',String(value))};
  let startY=0,startHeight=0;
  handle.addEventListener('pointerdown',event=>{
    if(event.pointerType==='mouse'&&event.button!==0)return;
    event.preventDefault();startY=event.clientY;startHeight=panel.getBoundingClientRect().height;
    handle.setPointerCapture(event.pointerId);document.body.classList.add('resizing-record-table');
  });
  handle.addEventListener('pointermove',event=>{
    if(!handle.hasPointerCapture(event.pointerId))return;
    panel.style.height=`${Math.max(160,startHeight+event.clientY-startY)}px`;
  });
  const finishResize=event=>{
    if(!handle.hasPointerCapture(event.pointerId))return;
    handle.releasePointerCapture(event.pointerId);saveHeight(panel.getBoundingClientRect().height);
    document.body.classList.remove('resizing-record-table');
  };
  handle.addEventListener('pointerup',finishResize);handle.addEventListener('pointercancel',finishResize);
  handle.addEventListener('keydown',event=>{
    if(event.key==='ArrowUp'||event.key==='ArrowDown'){
      event.preventDefault();saveHeight(panel.getBoundingClientRect().height+(event.key==='ArrowDown'?40:-40));
    }else if(event.key==='Home'){
      event.preventDefault();localStorage.removeItem('ponto-record-scroll-height');panel.style.removeProperty('height');
    }
  });
}

function bind(){
  addLunchColumn();
  const drop=document.querySelector('#dropzone'),input=document.querySelector('#file');
  drop.onclick=()=>input.click(); input.onchange=()=>upload(input.files[0]);
  drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();upload(e.dataTransfer.files[0])};
  document.querySelector('#search')?.addEventListener('input',e=>{state.search=e.target.value;render()});
  document.querySelector('#department')?.addEventListener('change',e=>{state.department=e.target.value;render()});
  document.querySelector('#all')?.addEventListener('change',e=>{filtered().forEach(item=>e.target.checked?state.selected.add(item.id):state.selected.delete(item.id));render()});
  document.querySelectorAll('.employee-check').forEach(el=>el.onchange=()=>{const id=Number(el.dataset.id);state.selected.has(id)?state.selected.delete(id):state.selected.add(id);render()});
  document.querySelectorAll('.time-edit').forEach(el=>el.addEventListener('input',()=>{const record=state.detail.records[Number(el.dataset.record)];record[el.dataset.field]=el.value||null;state.detailDirty=true;state.detailSaveError='';saveDraft();updateDetailCounts();const status=document.querySelector('#edit-status');if(status){status.textContent=state.detailBackupError||'Rascunho salvo neste navegador; salve para aplicar nesta sessão.';status.classList.toggle('save-error',Boolean(state.detailBackupError))}const countButton=document.querySelector('[data-backup-count]');if(countButton){const count=localDraftCount();countButton.textContent=`Apagar cópias locais (${count})`;countButton.disabled=!count}const save=document.querySelector('[data-action="save-detail"]');if(save)save.disabled=false}));
  document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>view(Number(el.dataset.view)));
  document.querySelectorAll('[data-pdf]').forEach(el=>el.onclick=()=>openExportReview('employee',[Number(el.dataset.pdf)]));
  document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));
  document.querySelector('.drawer-backdrop')?.addEventListener('mousedown',e=>{if(e.target.classList.contains('drawer-backdrop'))closeDetail()});
  document.querySelector('.review-backdrop')?.addEventListener('mousedown',e=>{if(e.target.classList.contains('review-backdrop'))cancelExportReview()});
  document.onkeydown=event=>{if(event.key==='Escape'&&state.review)cancelExportReview();else if(event.key==='Escape'&&state.detail)closeDetail()};
  document.querySelector('[data-action="confirm-export"]')?.focus();
  bindRecordResize();
}
async function upload(file){if(!file)return;const message=document.querySelector('#message');message.innerHTML='<div class="diagnostic">Processando planilha...</div>';const body=new FormData();body.append('file',file);try{const response=await fetch('/api/import',{method:'POST',body});const payload=await response.json();if(!response.ok)throw Error(payload.error);state.data=payload;state.selected=new Set(payload.employees.map(item=>item.id));state.detail=null;state.detailDirty=false;state.review=null;state.localBackupNotice='';render()}catch(error){message.innerHTML=`<div class="error">${esc(error.message)}</div>`}}
async function view(id){const response=await fetch(url(`/employee/${id}`));const payload=await response.json();if(response.ok){state.detailIdentity=draftIdentity(payload);state.detailKey=draftKey(state.detailIdentity);const restored=restoreDraft(payload,state.detailKey,state.detailIdentity);state.detailBackupAvailable=Boolean(restored);state.detailBackupError='';state.detailDirty=Boolean(restored?.changed);state.detailSaveError='';calculateWorkload(payload);state.data.employees[payload.id]=payload;state.detail=payload;render()}else alert(payload.error)}
function updateDetailCounts(){const employee=calculateWorkload(state.detail),totals=finalizeRecordTotals(recordTotals(employee));state.data.employees[employee.id]=employee;document.querySelector('#detail-count').textContent=employee.time_count;document.querySelector('#detail-days').textContent=employee.days_with_records;document.querySelector('#detail-worked').textContent=employee.worked_time;document.querySelector('#detail-expected').textContent=employee.expected_time;document.querySelector('#detail-balance').textContent=employee.balance_time;document.querySelector('#detail-required-total').textContent=formatDuration(totals.required);document.querySelector('#detail-worked-total').textContent=formatDuration(totals.worked);document.querySelector('#detail-balance-total').textContent=formatBalance(totals.balance);employee.records.forEach((record,index)=>{document.querySelector(`[data-lunch="${index}"]`)&&showLunch(document.querySelector(`[data-lunch="${index}"]`),record);document.querySelector(`[data-daily-required="${index}"]`).textContent=record.required_time;document.querySelector(`[data-daily-total="${index}"]`).textContent=record.worked_time;document.querySelector(`[data-daily-balance="${index}"]`).textContent=record.balance_time});let warning=document.querySelector('#incomplete-warning');if(employee.incomplete_day_count){if(!warning){warning=document.createElement('span');warning.id='incomplete-warning';warning.className='incomplete-warning';document.querySelector('.drawer-stats').append(warning)}warning.textContent=`${employee.incomplete_day_count} dia(s) sem os quatro horários principais. Não contabilizado(s), conforme a calculadora.`}else warning?.remove();let lunchWarning=document.querySelector('#lunch-warning');if(employee.lunch_excess_day_count){if(!lunchWarning){lunchWarning=document.createElement('span');lunchWarning.id='lunch-warning';lunchWarning.className='incomplete-warning';document.querySelector('.drawer-stats').append(lunchWarning)}lunchWarning.textContent=`${employee.lunch_excess_day_count} intervalo(s) de almoço acima de 1h30; o excedente está destacado na tabela.`}else lunchWarning?.remove();document.querySelector('.weekly-summary').outerHTML=weeklySummary(employee);const row=document.querySelector(`[data-employee-row="${employee.id}"]`);if(row){row.querySelector('[data-worked-value]').textContent=employee.worked_time;row.querySelector('[data-balance-value]').textContent=employee.balance_time}}
async function saveDetail(){if(!state.detailDirty)return true;const button=document.querySelector('[data-action="save-detail"]');const status=document.querySelector('#edit-status');if(button)button.disabled=true;if(status){status.textContent='Salvando alterações...';status.classList.remove('save-error')}try{const response=await fetch(url(`/employee/${state.detail.id}/records`),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({records:state.detail.records.map(record=>({shift1_start:record.shift1_start,shift1_end:record.shift1_end,shift2_start:record.shift2_start,shift2_end:record.shift2_end,overtime_start:record.overtime_start,overtime_end:record.overtime_end}))})});const payload=await response.json();if(!response.ok)throw Error(payload.error||'Não foi possível salvar as alterações.');state.detail=payload;state.data.employees[payload.id]=payload;state.detailDirty=false;state.detailSaveError='';state.detailBackupError='';calculateWorkload(payload);render();return true}catch(error){state.detailSaveError=error.message;if(status){status.textContent=error.message;status.classList.add('save-error')}if(button)button.disabled=false;return false}}
function openExportReview(kind,ids=null){if(kind==='selected'&&!ids?.length)return;if(kind==='combined'&&!ids?.length)return;state.review={kind,ids:ids==null?null:[...ids]};render()}
function cancelExportReview(){state.review=null;render()}
async function confirmExport(){const review=state.review;if(!review)return;state.review=null;if(review.kind==='detail'&&state.detailDirty){render();if(!await saveDetail()){state.review=review;render();return}}const suffix=review.kind==='detail'||review.kind==='employee'?`/employee/${review.ids[0]}/pdf`:review.kind==='combined'?`/combined.pdf?ids=${review.ids.join(',')}`:review.kind==='selected'?`/selected.zip?ids=${review.ids.join(',')}`:'/selected.zip';download(suffix)}
function clearLocalBackups(){const count=localDraftCount();if(!count)return;if(!confirm(`Apagar ${count} cópia(s) local(is) de horários deste navegador?`))return;for(const key of Object.keys(localStorage))if(key.startsWith(draftPrefix))localStorage.removeItem(key);state.detailBackupAvailable=false;state.localBackupNotice='Cópias locais apagadas.';if(state.detailDirty)state.detailBackupError='Cópia local apagada; salve as alterações antes de sair.';render()}
function closeDetail(){if(state.detailDirty&&!state.detailBackupAvailable&&!confirm('A cópia local falhou. Fechar pode perder as alterações desta sessão. Deseja fechar?'))return;state.detail=null;state.detailDirty=false;state.detailSaveError='';state.detailBackupError='';render()}
function action(name){if(name==='reset'){if(state.detailDirty&&!state.detailBackupAvailable&&!confirm('Não foi possível guardar as últimas alterações neste navegador. Importar outro arquivo pode perdê-las. Continuar?'))return;state.data=null;state.detail=null;state.detailDirty=false;state.selected.clear();render()}if(name==='diagnostic'){state.diagnostic=!state.diagnostic;render()}if(name==='close')closeDetail();if(name==='print')window.print();if(name==='save-detail')saveDetail();if(name==='detail-pdf')openExportReview('detail',[state.detail.id]);if(name==='cancel-export')cancelExportReview();if(name==='confirm-export')confirmExport();if(name==='clear-backups')clearLocalBackups();if(name==='selected')openExportReview('selected',[...state.selected]);if(name==='allzip')openExportReview('allzip');if(name==='combined')openExportReview('combined',[...state.selected])}
render();
